#include <bits/stdc++.h>
using namespace std;

using ll = long long;

void solve() {
    int n;
    ll l, r, x;
    cin >> n >> l >> r >> x;

    vector<ll> v(n);
    for (ll& value : v) cin >> value;

    ll ans = 0;

    for (ll mask = 0; mask < (1LL << n); ++mask) {
        if (__builtin_popcountll(mask) < 2) continue;

        ll sum = 0;
        ll mn = LLONG_MAX;
        ll mx = LLONG_MIN;

        for (int i = 0; i < n; ++i) {
            if (mask & (1LL << i)) {
                sum += v[i];
                mn = min(mn, v[i]);
                mx = max(mx, v[i]);
            }
        }

        if (sum >= l && sum <= r && mx - mn >= x) {
            ++ans;
        }
    }

    cout << ans << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}

